304		entry := HookEntry{
305			Type:    "command",
306			Command: command,
307			Timeout: 30,
308		}
309	
310		// Add to an existing group with null matcher, or create a new one
311		for i, group := range groups {
312			if group.Matcher == nil {
313				groups[i].Hooks = append(groups[i].Hooks, entry)
314				return groups
315			}
316		}
317		return append(groups, MatcherGroup{
318			Matcher: nil,
